def show_workers(queues, raw, by_queue, queue_class, worker_class, connection: Redis):
    workers = set()
    if queues:
        for queue in queues:
            for worker in worker_class.all(queue=queue, connection=connection):
                workers.add(worker)
    else:
        for worker in worker_class.all(connection=connection):
            workers.add(worker)

    if not by_queue:
        for worker in workers:
            queue_names = ', '.join(worker.queue_names())
            name = f'{worker.name} ({worker.hostname} {worker.ip_address} {worker.pid})'
            if not raw:
                line = (
                    f'{name}: {state_symbol(worker.get_state())} {queue_names}. '
                    f'jobs: {worker.successful_job_count} finished, {worker.failed_job_count} failed'
                )
                click.echo(line)
            else:
                line = (
                    f'worker {name} {worker.get_state()} {queue_names}. '
                    f'jobs: {worker.successful_job_count} finished, {worker.failed_job_count} failed'
                )
                click.echo(line)

    else:
        # Display workers by queue
        queue_dict = {}
        for queue in queues:
            queue_dict[queue] = worker_class.all(queue=queue, connection=connection)

        if queue_dict:
            max_length = max(len(q.name) for (q,) in queue_dict.keys())
        else:
            max_length = 0

        for queue in queue_dict:
            if queue_dict[queue]:
                queues_str = ', '.join(
                    sorted(map(lambda w: f'{w.name} ({state_symbol(w.get_state())})', queue_dict[queue]))
                )
            else:
                queues_str = '–'
            click.echo('{} {}'.format(pad(queue.name + ':', max_length + 1), queues_str))

    if not raw:
        click.echo(f'{len(workers)} workers, {len(queues)} queues')


def show_both(queues, raw, by_queue, queue_class, worker_class, connection: Redis):
    show_queues(queues, raw, by_queue, queue_class, worker_class, connection)
    if not raw:
        click.echo('')
    show_workers(queues, raw, by_queue, queue_class, worker_class, connection)
    if not raw:
        click.echo('')

